select 
	flow_cell_metadata.cell_id,
	flow_pattern,
	ne_material,
	pe_material,
	membrane,
	membrane_size,
	ne_active,
	initial_ne_active, 
	pe_active,    
	initial_pe_active,      
	ne_volume, 
	pe_volume,
	flow_rate,
	test_type,
	tester,
	test,
	status,
	parent_id
from  
	flow_cell_metadata inner join flow_cycle_metadata on flow_cell_metadata.cell_id = flow_cycle_metadata.cell_id 
where
    flow_pattern IN ({{flow_pattern}}) and
    ne_material IN ({{ne_material}}) and
    pe_material IN ({{pe_material}}) and
    membrane IN ({{membrane}}) and
    membrane_size IN ({{membrane_size}}) and
    ne_active IN ({{ne_active}}) and
    initial_ne_active IN ({{initial_ne_active}}) and 
    pe_active IN ({{pe_active}}) and
    initial_pe_active IN ({{initial_pe_active}}) and  
    ne_volume IN ({{ne_volume}}) and
    pe_volume IN ({{pe_volume}}) and
    flow_rate IN ({{flow_rate}}) and
    status = 'completed'
order by  
	flow_cycle_metadata.cell_id                  